style.css:
@-moz-document domain("web.grindr.com") {
/* Tło i tekst */
html,
body,
#root {
  background: #ffffff !important;
  color: #000000 !important;
}

/* Ogólne nadpisanie tekstu i obramowań */
html *,
body * {
  color: #000000 !important;
  text-shadow: none !important;
  box-shadow: none !important;
  border-color: #d7e8d2 !important;
}

/* Typowe kontenery */
div,
section,
article,
main,
aside,
header,
footer,
nav,
ul,
li {
  background-color: #ffffff !important;
  color: #000000 !important;
}

/* Formularze */
input,
textarea,
select,
button {
  background: #ffffff !important;
  color: #000000 !important;
  border: 1px solid #d7e8d2 !important;
}

/* Placeholder */
input::placeholder,
textarea::placeholder {
  color: #444444 !important;
  opacity: 1 !important;
}

/* Linki */
a,
a:link,
a:visited,
a:hover,
a:active {
  color: #000000 !important;
}

/* Ikony */
svg,
svg path,
svg circle,
svg rect,
svg polygon {
  fill: currentColor !important;
  stroke: currentColor !important;
  color: #000000 !important;
}

/* Bladozielone akcenty */
button,
[role="button"],
[aria-selected="true"],
[aria-pressed="true"],
[aria-current="true"],
.active,
.selected {
  background: #dcefd7 !important;
  color: #000000 !important;
  border-color: #c9e4c2 !important;
}

/* Hover i focus */
button:hover,
button:focus,
[role="button"]:hover,
[role="button"]:focus,
a:hover,
input:focus,
textarea:focus,
select:focus {
  background: #eef8eb !important;
  color: #000000 !important;
  border-color: #c9e4c2 !important;
  outline: none !important;
}

/* Tekst */
span,
label,
small,
strong,
p,
h1, h2, h3, h4, h5, h6 {
  color: #000000 !important;
}

/* Próba nadpisania żółtych / złotych akcentów */
[class*="yellow"],
[class*="amber"],
[class*="gold"],
[class*="Yellow"],
[class*="Amber"],
[class*="Gold"],
[style*="yellow"],
[style*="Yellow"],
[style*="#ff0"],
[style*="#FF0"],
[style*="#ffd"],
[style*="#FFD"] {
  background-color: #dcefd7 !important;
  color: #000000 !important;
  border-color: #c9e4c2 !important;
}

/* Wyłączenie części agresywnych teł inline */
[style*="background-image"] {
  background-image: none !important;
}

/* Scrollbar */
*::-webkit-scrollbar {
  width: 10px !important;
  height: 10px !important;
}

*::-webkit-scrollbar-track {
  background: #f4f4f4 !important;
}

*::-webkit-scrollbar-thumb {
  background: #cfe3ca !important;
  border-radius: 8px !important;
}

/* Zaznaczenie tekstu */
::selection {
  background: #c9e4c2 !important;
  color: #000000 !important;
}
}
